 * @typedef {{ subjectId: string, status: "accepted" | "blocked", findings: CoreDomainModelAndStableIdentifiersFinding[] }} CoreDomainModelAndStableIdentifiersResult
 */

/**
 * Evaluate one input against the core domain model and stable identifiers policy.
 * @param {CoreDomainModelAndStableIdentifiersInput} input
 * @returns {CoreDomainModelAndStableIdentifiersResult}
 */
export function evaluateCoreDomainModelAndStableIdentifiers(input) {
	const findings = [];
	if (!input || typeof input.id !== "string" || input.id.length === 0) {
		return { subjectId: "unknown", status: "blocked", findings: [{ code: "core-domain-model-and-stable-identifiers/missing-id", severity: "critical", evidence: ["input.id is required"] }] };
	}
	if (!Number.isFinite(input.quantity) || input.quantity < 0) {
		findings.push({ code: "core-domain-model-and-stable-identifiers/quantity-range", severity: "critical", evidence: [`quantity ${input.quantity} is outside [0, ∞)`] });
	}
	if (!/^\d{4}-\d{2}-\d{2}T/.test(input.occurredAt ?? "")) {
		findings.push({ code: "core-domain-model-and-stable-identifiers/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "core-domain-model-and-stable-identifiers/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

